create table if not exists public.vocabulary_sets (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade default auth.uid(),name text not null check (char_length(name) between 1 and 60),created_at timestamptz not null default now());
create table if not exists public.vocabulary_words (id uuid primary key default gen_random_uuid(),set_id uuid not null references public.vocabulary_sets(id) on delete cascade,word text not null,meaning text not null,hidden_until timestamptz,created_at timestamptz not null default now());
alter table public.vocabulary_sets enable row level security;alter table public.vocabulary_words enable row level security;
create policy "Users manage their own sets" on public.vocabulary_sets for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "Users manage words in their own sets" on public.vocabulary_words for all to authenticated using (exists (select 1 from public.vocabulary_sets s where s.id = set_id and s.user_id = auth.uid())) with check (exists (select 1 from public.vocabulary_sets s where s.id = set_id and s.user_id = auth.uid()));
